import json
import re
import sys

def parse_script(text: str):
    nodes = []
    edges = []

    sections = []
    current_section = None

    lines = text.splitlines()
    for line in lines:
        line_stripped = line.strip()
        if not line_stripped:
            continue
        if line_stripped.startswith('[') and line_stripped.endswith(']'):
            if current_section:
                sections.append(current_section)
            current_section = {'id': line_stripped[1:-1], 'lines': []}
        else:
            if current_section:
                current_section['lines'].append(line_stripped)
    if current_section:
        sections.append(current_section)

    node_map = {}

    for section in sections:
        node_id = section['id']
        content_lines = section['lines']

        # Determine if it's a choice or a line
        is_choice = any(re.match(r'^\d+\.', l) for l in content_lines)

        if is_choice:
            node = {
                "id": node_id,
                "text": "",
                "speaker": "",
                "type": "choice"
            }
            nodes.append(node)
            node_map[node_id] = node
            for l in content_lines:
                match = re.match(r'^\d+\.\s*(.*?)\s*->\s*(.*)$', l)
                if match:
                    choice_text = match.group(1).strip()
                    target = match.group(2).strip()
                    edges.append({
                        "from": node_id,
                        "to": target,
                        "text": choice_text
                    })
        else:
            found_line = False
            for l in content_lines:
                # Match "Speaker: Text -> Target"
                match = re.match(r'^([^:]+):\s*(.*?)\s*->\s*(.*)$', l)
                if match:
                    speaker = match.group(1).strip()
                    text_content = match.group(2).strip()
                    target = match.group(3).strip()

                    node = {
                        "id": node_id,
                        "text": text_content,
                        "speaker": speaker,
                        "type": "line"
                    }
                    nodes.append(node)
                    node_map[node_id] = node
                    edges.append({
                        "from": node_id,
                        "to": target,
                        "text": ""
                    })
                    found_line = True
                    break

            if not found_line:
                # Fallback if no speaker but has target
                for l in content_lines:
                    if '->' in l:
                        parts = l.split('->')
                        text_part = parts[0].strip()
                        target = parts[1].strip()
                        node = {
                            "id": node_id,
                            "text": text_part,
                            "speaker": "",
                            "type": "line"
                        }
                        nodes.append(node)
                        node_map[node_id] = node
                        edges.append({
                            "from": node_id,
                            "to": target,
                            "text": ""
                        })
                        found_line = True
                        break

                if not found_line:
                    # Empty or text-only section
                    node = {
                        "id": node_id,
                        "text": " ".join(content_lines),
                        "speaker": "",
                        "type": "line"
                    }
                    nodes.append(node)
                    node_map[node_id] = node

    # Add missing target nodes (like "End")
    defined_ids = set(n['id'] for n in nodes)
    all_targets = set(e['to'] for e in edges)
    for t in all_targets:
        if t not in defined_ids:
            nodes.append({
                "id": t,
                "text": "",
                "speaker": "",
                "type": "line"
            })
            defined_ids.add(t)

    # Constraint 1: Reachability check and filtering
    if nodes:
        first_node_id = nodes[0]['id']
        reachable = {first_node_id}
        queue = [first_node_id]

        adjacency = {}
        for edge in edges:
            if edge['from'] not in adjacency:
                adjacency[edge['from']] = []
            adjacency[edge['from']].append(edge['to'])

        while queue:
            current = queue.pop(0)
            for neighbor in adjacency.get(current, []):
                if neighbor not in reachable:
                    reachable.add(neighbor)
                    queue.append(neighbor)

        nodes = [n for n in nodes if n['id'] in reachable]
        edges = [e for e in edges if e['from'] in reachable and e['to'] in reachable]

    return {"nodes": nodes, "edges": edges}

def generate_dot(graph):
    dot = ["digraph Dialogue {"]
    dot.append("    node [shape=box];")

    for node in graph['nodes']:
        if node['type'] == 'choice':
            label = f"[{node['id']}]"
        else:
            if node['speaker'] and node['text']:
                label = f"{node['speaker']}: {node['text']}"
            elif node['text']:
                label = node['text']
            else:
                label = node['id']

        # Escape quotes and backslashes
        label = label.replace('\\', '\\\\').replace('"', '\\"')
        dot.append(f'    "{node["id"]}" [label="{label}"];')

    for edge in graph['edges']:
        label = edge['text'].replace('\\', '\\\\').replace('"', '\\"')
        dot.append(f'    "{edge["from"]}" -> "{edge["to"]}" [label="{label}"];')

    dot.append("}")
    return "\n".join(dot)

if __name__ == "__main__":
    try:
        with open("/app/script.txt", "r") as f:
            script_text = f.read()

        graph = parse_script(script_text)

        with open("/app/dialogue.json", "w") as f:
            json.dump(graph, f, indent=2)

        dot_content = generate_dot(graph)
        with open("/app/dialogue.dot", "w") as f:
            f.write(dot_content)
    except Exception as e:
        print(f"Error: {e}")
        sys.exit(1)

